mapper.select:
SELECT q.id, q.dept_id, q.question_no, q.position_id, q.qtype, q.difficulty, q.knowledge_point,
       q.stem, q.options_json, q.attachment_url, q.answer, q.analysis, q.score, q.is_subjective, q.status
FROM question q
WHERE q.deleted = 0 AND q.status = 1
  AND q.dept_id = #{deptId}

  AND q.knowledge_point = #{point}


  AND q.qtype = #{qtype}


  AND q.id NOT IN
  #{eid}

ORDER BY RAND()
LIMIT #{limit}

SELECT u.user_id AS userId, u.user_name AS userName, u.nick_name AS nickName, u.dept_id AS deptId, d.dept_name AS deptName, pos.position_name AS positionName, u.user_status AS userStatus FROM sys_user u LEFT JOIN sys_dept d ON d.dept_id = u.dept_id AND d.del_flag = '0' LEFT JOIN position pos ON pos.id = u.position_id WHERE u.del_flag = '0' AND u.status = '0' AND u.user_status = 'PRE_TRAINEE'
AND u.dept_id = #{deptId}
ORDER BY u.dept_id, u.user_id
